// src/pages/Selections.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import Card from "../components/common/Card";
import * as SelectionData from "../constants/selection";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Selections.module.css"; // 引入新樣式

// 引入你的小幫手影片
import eveVideo from "../assets/eve_sdm_talk.mp4";

const Selections = () => {
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const videoRef = useRef(null);

  const [selectedId, setSelectedId] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // 1. 同步頂部資訊，並在載入時觸發小幫手語音與影片同步
  useEffect(() => {
    const welcomeText = `${allAnswers.userName || "您"}您好，我可以幫您什麼呢？請根據您想了解的問題選擇。`;

    setHeroData({
      imageUrl: "",
      title: welcomeText,
      description: "請點擊上方影片可重複聆聽引導喔。",
    });

    // 自動播放小幫手語音導覽
    handlePlaySpeech(welcomeText);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [setHeroData, allAnswers.userName]);

  // 🔊 語音與影片連動核心函式
  const handlePlaySpeech = (text) => {
    if (!window.speechSynthesis || !videoRef.current) return;

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";
    utterance.rate = 1.0;

    utterance.onstart = () => {
      setIsPlaying(true);
      if (videoRef.current) {
        videoRef.current.muted = true; // 靜音影片本身
        videoRef.current
          .play()
          .catch((err) => console.log("影片播放受阻：", err));
      }
    };

    utterance.onend = () => {
      setIsPlaying(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0; // 停下並回到閉嘴狀態
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      if (videoRef.current) videoRef.current.pause();
    };

    window.speechSynthesis.speak(utterance);
  };

  // 允許點擊影片重新播放語音
  const handleReplayVideo = () => {
    const welcomeText = `${allAnswers.userName || "您"}您好，我可以幫您什麼呢？請根據您想了解的問題選擇。`;
    handlePlaySpeech(welcomeText);
  };

  // 2. 確定跳轉邏輯
  const handleConfirm = () => {
    if (!selectedId) {
      alert("請先選擇一個方案");
      return;
    }

    if (window.speechSynthesis) window.speechSynthesis.cancel();
    if (videoRef.current) videoRef.current.pause();

    const paths = {
      1: "/SDM",
      2: "/chatbot",
    };

    const targetPath = paths[selectedId];
    if (targetPath) {
      navigate(targetPath);
    } else {
      console.warn("未定義的路徑");
    }
  };

  const currentSelection = SelectionData.selectionList.find(
    (s) => s.id === selectedId,
  );

  return (
    <div className={styles.pageContainer}>
      {/* 劇場大畫面背景：小幫手視訊框 */}
      <div className={styles.theatreVideoContainer} onClick={handleReplayVideo}>
        <video
          ref={videoRef}
          src={eveVideo}
          playsInline
          webkit-playsinline="true"
          preload="auto"
          loop
          className={styles.theatreVideo}
        />

        {/* 音訊播放狀態小標籤 */}
        {isPlaying && (
          <div className={styles.audioBadge}>
            <span className={styles.audioDot}></span> 小幫手正在引導中...
          </div>
        )}

        {/* 核心魔法：直接疊加在影片上方的選單面板 */}
        <div
          className={styles.overlayMenuPanel}
          onClick={(e) => e.stopPropagation()}
        >
          <div className={`${styles.container} ${styles.fadeIn}`}>
            {/* 選擇列表區塊 */}
            <div className={styles.cardList}>
              {SelectionData.selectionList.map((item) => (
                <Card
                  key={item.id}
                  title={item.title}
                  description={item.description}
                  isActive={selectedId === item.id}
                  onClick={() => setSelectedId(item.id)}
                />
              ))}
            </div>

            {/* 按鈕群組區塊 */}
            <div className={styles.buttonGroup}>
              <Button onClick={handleConfirm} fullWidth>
                {selectedId
                  ? `進入 ${currentSelection?.title} ➔`
                  : "請選擇上方方案"}
              </Button>

              <Button variant="outline" onClick={() => navigate("/")} fullWidth>
                返回修改基本資料
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Selections;
